      body: 'Spoken Persian follows regular patterns. <b>â</b> before <b>n</b> or <b>m</b> often becomes <b>u</b>: <i>khâne → khune, ân → un</i>. Many verb stems shorten (<i>rav → r, gu → g, khâh → khâ, tavân → tun</i>), and the endings <i>-ad</i> and <i>-and</i> become <i>-e</i> and <i>-an</i>. <i>ast</i> becomes <i>-e</i> after a consonant, <i>râ</i> becomes <i>ro</i> (or <i>-o</i> after a consonant), and <i>-hâ</i> becomes <i>-â</i> after a consonant.',
