          en: 'In the past, most Iranian mothers sang their children to sleep with lullabies. A lullaby is a short, gentle poem sung in a soft voice, and every region of Iran has its own kind. Grandmothers, too, would sit the children around them at night and tell them stories. Sometimes these stories made the children laugh, and sometimes they were so exciting that they chased sleep away.',
