      body: 'Add <b>-i</b> to an adjective or noun to make an abstract noun: <i>âzâd → âzâdi</i> ("free → freedom"), <i>dust → dusti</i> ("friend → friendship"). Words ending in a silent <i>-e</i> take <b>-egi</b> instead: <i>khaste → khastegi</i> ("tired → tiredness"), <i>zende → zendegi</i> ("alive → life"). Add <b>-esh</b> to a <b>present stem</b> to name an action: <i>âmuz → âmuzesh</i> ("teaching"), <i>pazir → paziresh</i> ("acceptance"), <i>kâh → kâhesh</i> ("decrease"). Written and scientific Persian loves these nouns, chained with the ezâfe.',
