          tr: "dar sâlhâ-ye akhir hush-e masnu'i niz vâred-e zendegi-ye mardom shode ast. dâneshjuyân az ân barâ-ye tarjome va neveshtan estefâde mikonand va barkhi sherkathâ barâ-ye pâsokh dâdan be moshtariyân az ân komak migirand. pazhuheshgarân-e dâneshgâhhâ-ye Irân ham dar zamine-ye pardâzesh-e zabân-e fârsi kâr mikonand, zirâ bishtar-e in fanâvarihâ dar âghâz barâ-ye zabân-e engelisi sâkhte shode-and va fârsi râ be khubi nemifahmidand.",
          en: "In recent years artificial intelligence has entered people's lives too. Students use it for translating and writing, and some companies use it to answer customers. Researchers at Iranian universities are also working on Persian language processing, because most of these technologies were first built for English and did not understand Persian well.",
