    reading: {
      title: 'How an office letter is built',
      paragraphs: [
        {
          fa: 'نامه\u200cهای اداری در ایران ساختار مشخصی دارند. در بالای نامه، سمت چپ، تاریخ و شماره\u200cی نامه نوشته می\u200cشود و پایین\u200cتر، نام گیرنده با عنوانی محترمانه مانند «جناب آقای» یا «سرکار خانم» می\u200cآید. سپس خطی با عنوان «موضوع» قرار می\u200cگیرد که در چند کلمه می\u200cگوید نامه درباره\u200cی چیست. متن نامه معمولاً با «با سلام و احترام» آغاز می\u200cشود.',
          tr: "nâmehâ-ye edâri dar Irân sâkhtâr-e moshakhkhasi dârand. dar bâlâ-ye nâme, samt-e chap, târikh va shomâre-ye nâme neveshte mishavad va pâyintar, nâm-e girande bâ onvâni mohtaramâne mânand-e «jenâb-e âghâ-ye» yâ «sarkâr khânom» miâyad. sepas khatti bâ onvân-e «mowzu'» gharâr migirad ke dar chand kalame miguyad nâme darbâre-ye chist. matn-e nâme ma'mulan bâ «bâ salâm va ehterâm» âghâz mishavad.",
          en: 'Office letters in Iran have a clear structure. At the top of the letter, on the left, go the date and the letter number, and further down comes the name of the recipient with a respectful title such as "jenâb-e âghâ-ye" (Mr) or "sarkâr khânom" (Mrs/Ms). Then there is a line headed "mowzu\'" (subject) that says in a few words what the letter is about. The body of the letter usually opens with "bâ salâm va ehterâm".',
        },
        {
          fa: 'در بدنه\u200cی نامه، نویسنده ابتدا موضوع را کوتاه توضیح می\u200cدهد. اگر نامه پاسخ به نامه\u200cی دیگری باشد، از عبارت\u200cهایی مانند «پیرو نامه\u200cی قبلی» یا «عطف به نامه\u200cی شما» استفاده می\u200cشود. در نامه\u200cی شکایت، بهتر است لحن مؤدبانه حفظ شود و مشکل با تاریخ و جزئیات دقیق شرح داده شود؛ نامه\u200cای که با عصبانیت نوشته شده باشد، معمولاً کمتر نتیجه می\u200cدهد. درخواست هم اغلب با «خواهشمند است» و فعلی در وجه التزامی بیان می\u200cشود.',
          tr: "dar badane-ye nâme, nevisande ebtedâ mowzu' râ kutâh towzih midahad. agar nâme pâsokh be nâme-ye digari bâshad, az ebârathâyi mânand-e «peyrov-e nâme-ye ghabli» yâ «'atf be nâme-ye shomâ» estefâde mishavad. dar nâme-ye shekâyat, behtar ast lahn-e mo'addabâne hefz shavad va moshkel bâ târikh va joz'iyât-e daghigh sharh dâde shavad; nâme-i ke bâ asabâniyat neveshte shode bâshad, ma'mulan kamtar natije midahad. darkhâst ham aghlab bâ «khâheshmand ast» va fe'li dar vajh-e eltezâmi bayân mishavad.",
          en: 'In the body of the letter, the writer first explains the matter briefly. If the letter replies to another one, phrases such as "peyrov-e nâme-ye ghabli" (further to the previous letter) or "\'atf be nâme-ye shomâ" (with reference to your letter) are used. In a complaint, it is better to keep a polite tone and to describe the problem with dates and precise details; a letter written in anger usually achieves less. The request itself is often expressed with "khâheshmand ast" and a verb in the subjunctive.',
        },
        {
          fa: 'در پایان، نویسنده از گیرنده تشکر می\u200cکند. جمله\u200cی «پیشاپیش از همکاری شما سپاسگزارم» بسیار رایج است و پس از آن، نام، سمت و امضای نویسنده می\u200cآید. اگر مدرکی همراه نامه فرستاده شود، در پایین نامه با کلمه\u200cی «پیوست» به آن اشاره می\u200cشود. امروزه بسیاری از این نامه\u200cها به شکل ایمیل فرستاده می\u200cشوند، اما قواعد اصلی تغییری نکرده است؛ فقط ایمیل\u200cها کمی کوتاه\u200cترند و فعل\u200cهای بسیار رسمی مانند «می\u200cگردد» و «می\u200cنماید» در آن\u200cها کمتر دیده می\u200cشود.',
          tr: "dar pâyân, nevisande az girande tashakkor mikonad. jomle-ye «pishâpish az hamkâri-ye shomâ sepâsgozâram» besyâr râyej ast va pas az ân, nâm, semat va emzâ-ye nevisande miâyad. agar madraki hamrâh-e nâme ferestâde shavad, dar pâyin-e nâme bâ kalame-ye «peyvast» be ân eshâre mishavad. emruze besyâri az in nâmehâ be shekl-e imeyl ferestâde mishavand, ammâ ghavâ'ed-e asli taghyiri nakarde ast; faghat imeylhâ kami kutâhtarand va fe'lhâ-ye besyâr rasmi mânand-e «migardad» va «minamâyad» dar ânhâ kamtar dide mishavad.",
          en: 'At the end, the writer thanks the recipient. The sentence "pishâpish az hamkâri-ye shomâ sepâsgozâram" (thank you in advance for your cooperation) is very common, and after it come the writer\'s name, position and signature. If a document is sent with the letter, it is mentioned at the bottom with the word "peyvast" (attachment). Today many of these letters are sent as emails, but the main rules have not changed; emails are just a little shorter, and very formal verbs such as "migardad" and "minamâyad" are seen less often in them.',
        },
      ],
      questions: [
        {
          q: 'The body of a letter begins «peyrov-e nâme-ye ghabli…». What can you conclude?',
          options: [
            'It is the first contact between the two sides',
            'It follows up an earlier letter',
            'It is a complaint about a faulty product',
            'It was sent as an attachment',
          ],
          answer: 1,
        },
        {
          q: 'Why does the text advise keeping a complaint polite?',
          options: [
            'Because the law requires it',
            'Because a letter written in anger usually achieves less',
            'Because emails cannot contain complaints',
            'Because the recipient is always a minister',
          ],
          answer: 1,
        },
        {
          q: 'What does the last paragraph suggest about formal emails compared with paper letters?',
          options: [
            'They follow completely different rules',
            'They are longer and more formal',
            'They keep the same basic rules but are a little shorter and less heavy',
            'They never open with bâ salâm va ehterâm',
          ],
          answer: 2,
        },
      ],
    },
