      body: 'Many Arabic words came into Persian with their Arabic plural. A <b>broken plural</b> changes the vowels inside the word: <i>ketâb → kotob</i>, <i>shakhs → ashkhâs</i>, <i>fekr → afkâr</i>. <b>Sound plurals</b> add an ending: <i>-ât</i> (<i>ettelâ\'ât</i>, and even on a few Persian words: <i>dehât, sabzijât</i>) and <i>-in</i> for people (<i>mosâferin</i>). In everyday Persian almost any noun can simply take <i>-hâ</i>, or <i>-ân</i> for people: <i>ketâbhâ, fekrhâ, mosâferân</i>. Arabic plurals sound formal or fixed, so keep them for set phrases and writing.',
