          optionsTr: ['har jâ ke zendegi koni, zabân-e mahalli râ yâd begir', 'har jâ ke zendegi kardi, zabân-e mahalli râ yâd gerefti', 'har jâ zendegi mikoni ke zabân-e mahalli râ yâd begir'],
          answer: 0,
          why: 'An open "wherever" takes the subjunctive (zendegi koni), and ke comes straight after har jâ.',
