          optionsTr: ['har vaght ke in âhang râ shenidam, yâd-e Shirâz biyoftam', 'har vaght in âhang râ beshenavam ke yâd-e Shirâz mioftam', 'har vaght ke in âhang râ mishenavam, yâd-e Shirâz mioftam'],
          answer: 2,
